///////// 1. 변수 및 선언 영역 /////////
scwin.CPBO = "";

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name ins_search
 * @description CP / 전자단기사채 마스터  목록 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) === false) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SSTD_CD_GRNT_DD, edt_ESTD_CD_GRNT_DD) === false) {
        return false;
    }

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);

    // cmb_CP_BND_TP_CD
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_detail
 * @description CP / 전자단기사채 마스터 상세 조회한다.
 * @param {String} STD_CD STD_CD
 * @param {*} FLAG FLAG
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_detail = async function(STD_CD, FLAG) {
    // CP / 전자단기사채
    /* CP_BND_TP_CD
    03417	BO	전자단기사채
    03417	CP	CP채권*/
    let queryId = "";
    dts_detail.removeAll();
    dts_REQCDCPCDTVLU.removeAll();
    if (FLAG === "") return;
    if (FLAG === "CP") {
        queryId = "lds.ins.stdcdcpbnd.select.readStdCdCpCpBndInfoView"; // CP  마스터 상세

    } else {
        queryId = "lds.ins.stdcdcpbnd.select.readStdCdCpBoBndInfoView"; // 전자단기사채  마스터 상세

    }

    //  alert( url);

    const sbmOptions = {
        id : "sbm_dts_detail",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_detail=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // CP / 전자단기 사채 신용등급
    const sbmOptions2 = {
        id : "sbm_dts_REQCDCPCDTVLU",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_REQCDCPCDTVLU=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
scwin.arrPar = new Array();

/**
     * @method
     * @name getParam
     * @description 전달 값을 정의한다.
     * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
     * @returns {void}
     * @hidden N
     */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드
    scwin.arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name setBoView
 * @description 전자단기사채 상세화면을 정의한다.
 * @param {*} SIMSA_YN SIMSA_YN
 * @param {String} LIST_STAT_CD LIST_STAT_CD
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setBoView = async function(SIMSA_YN, LIST_STAT_CD) {
    if (LIST_STAT_CD === "N" && SIMSA_YN === "Y") {
        await $c.win.alert(" 해당종목은 신규상장심사종목입니다. \n" + " 수정후에는 반드시 채권심사종목정보도 수정이 되도록 채권상장팀에 통보를 하셔야 됩니다.");
    } else if (LIST_STAT_CD === "Y") {
        // alert(" 상장채권은 수정할 수 없습니다. \n" + " 채권상장팀과 협의하시기 바랍니다.");
        btn_modify.setDisabled(true);
        btn_modify.setBackgroundImage("../img/ins/btn_modify_d.gif");
        btn_delete.setDisabled(true);
        btn_delete.setBackgroundImage("../img/ins/btn_delete_d.gif");

        // alert 삭제 및 비밀번호 초기화도 제어 추가 20140116
        btn_clearPwd.setDisabled(true);
        btn_clearPwd.setBackgroundImage("../img/ins/btn_clearPwd_d.gif");
    } else {
        btn_modify.setDisabled(false);
        btn_modify.setBackgroundImage("../img/ins/btn_modify.gif");
        btn_delete.setDisabled(false);
        btn_delete.setBackgroundImage("../img/ins/btn_delete.gif");
        btn_clearPwd.setDisabled(false);
        btn_clearPwd.setBackgroundImage("../img/ins/btn_clearPwd.gif");
    }
    if (cmb_BND_TP_CD.getValue() === "AB") {
        if (txb_BND_CLSS_CD.getValue() === "") {
            await $c.win.alert("특수채 발행기관 코드가 없습니다.");
        }
    }
};

/**
 * @method
 * @name ins_remove
 * @description CP/전자단기사채  삭제처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_remove = async function() {

    // dts_ListDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_ListDelete.insertRow();
    dts_ListDelete.setCellData(1, "STD_CD", txb_STD_CD.getValue());
    dts_ListDelete.setCellData(1, "ISU_NM", txb_ISU_NM.getValue());
    dts_ListDelete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
    dts_ListDelete.setCellData(1, "UNQ_ISU_NM", txb_UNQ_ISU_NM.getValue());
    dts_ListDelete.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
    dts_ListDelete.setCellData(1, "ISU_DD", edt_ISU_DD.getValue());
    dts_ListDelete.setCellData(1, "MUNIBND_TP_CD", cmb_MUNIBND_TP_CD.getValue());
    dts_ListDelete.setCellData(1, "BND_TP_CD", cmb_BND_TP_CD.getValue());
    trs_remove.KeyName = "toinb_dataid4";
    // [전환검토] trs_remove.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm,
    //     EMAIL : js_email
    // };
    const sbmOptions = {
        id : "sbm_trs_remove",
        action : "/StdCdCpBndInfoAction.do",
        ref : "dts_ListDelete",
        target : "trs_remove=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name ins_modify
 * @description CP/전자단기사채  표준코드  수정한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_modify = async function() {
    dts_detail.setCellData(dts_detail.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    dts_REQCDCPCDTVLU.setCellData(dts_REQCDCPCDTVLU.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    trs_modify.KeyName = "toinb_dataid4";
    // [전환검토] trs_modify.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm,
    //     EMAIL : js_email
    // };
    const sbmOptions = {
        id : "sbm_trs_modify",
        action : "/StdCdCpBndInfoAction.do",
        ref : "dts_Rst,dts_detail,dts_REQCDCPCDTVLU",
        target : "trs_modify=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name formCheck
 * @description 폼을 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.formCheck = async function() {
    if (txb_ISUR_CD.getValue() === "" || txb_ISUR_CD.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관코드"));
        txb_ISUR_CD.focus();
        return false;
    }
    if (txb_ISU_NM.getValue() === "" || txb_ISU_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글기준명"));
        txb_ISU_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 60, "한글기준명")) {
        txb_ISU_ABBRV.setValue("");
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (txb_ISU_ABBRV.getValue() === "" || txb_ISU_ABBRV.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글기준약명"));
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 20, "한글기준약명")) {
        txb_ISU_ABBRV.setValue("");
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (txb_ISU_ENG_NM.getValue() === "" || txb_ISU_ENG_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 60, "영문종목명")) {
        txb_ISU_ENG_NM.setValue("");
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (txb_ISU_ENG_ABBRV.getValue() === "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 20, "영문종목약명")) {
        txb_ISU_ENG_ABBRV.setValue("");
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (txb_UNQ_ISU_NM.getValue() === "" || txb_UNQ_ISU_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글고유명"));
        txb_UNQ_ISU_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_UNQ_ISU_NM, 20, "한글고유명")) {
        txb_UNQ_ISU_NM.setValue("");
        txb_UNQ_ISU_NM.focus();
        return false;
    }
    if (txb_UNQ_ISU_ENG_NM.getValue() === "" || txb_UNQ_ISU_ENG_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문고유명"));
        txb_UNQ_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_UNQ_ISU_ENG_NM, 20, "영문고유명")) {
        txb_UNQ_ISU_ENG_NM.setValue("");
        txb_UNQ_ISU_ENG_NM.focus();
        return false;
    }
    if (edt_ISU_DD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행일"));
        edt_ISU_DD.focus();
        return false;
    }
    if (edt_EXP_DD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "상환일(만기일)"));
        edt_EXP_DD.focus();
        return false;
    }
    if (fn_CheckDateObj(edt_ISU_DD, "발행일")) return false;
    if (fn_CheckDateObj(edt_EXP_DD, "상환일(만기일)")) return false;
    if (edt_YY1_BAS_YD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "이자율"));
        edt_YY1_BAS_YD.focus();
        return false;
    }
    /*if(getObjectValue(edt_DC_RT) == "" ) {
    	alert( getMessageParam("MSG-A005", "할인율") );
    	edt_DC_RT.focus();
    	return false;
    } */
    if (edt_EXP_PAY_AMT.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "금액"));
        edt_EXP_PAY_AMT.focus();
        return false;
    }
    /*if(getObjectValue(edt_DC_SALES) == "" ) {
    	alert( getMessageParam("MSG-A005", "할인매출액") );
    	edt_DC_SALES.focus();
    	return false;
    } */
    if (cmb_CURR_TP_CD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행통화"));
        cmb_CURR_TP_CD.focus();
        return false;
    }
    if (cmb_DOM_FORN_ISU_TP_CD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행구분"));
        cmb_DOM_FORN_ISU_TP_CD.focus();
        return false;
    }
    if (cmb_LIST_STAT_CD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "상장여부"));
        cmb_LIST_STAT_CD.focus();
        return false;
    }
    let CP_BND_TP_CD = dts_detail.getCellData(dts_detail.getRowPosition(), "CP_BND_TP_CD");
    if (CP_BND_TP_CD === "BO") {
        // 전자단기사채일경우
        if (cmb_BND_TP_CD.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "채권유형"));
            cmb_BND_TP_CD.focus();
            return false;
        }
        if (txb_BND_CLSS_CD.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "채권분류코드"));
            txb_BND_CLSS_CD.focus();
            return false;
        }
        if (txb_CFI_CD.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI코드"));
            txb_CFI_CD.focus();
            return false;
        }
    }

    // CFI체크
    if (cmb_cb_p_group.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_그룹"));
        cmb_cb_p_group.focus();
        return false;
    }
    if (cmb_cb_p_attr_1.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_1차속성"));
        cmb_cb_p_attr_1.focus();
        return false;
    }
    if (cmb_cb_p_attr_2.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_2차속성"));
        cmb_cb_p_attr_2.focus();
        return false;
    }
    if (cmb_cb_p_attr_3.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_3차속성"));
        cmb_cb_p_attr_3.focus();
        return false;
    }
    if (cmb_cb_p_attr_4.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_4차속성"));
        cmb_cb_p_attr_4.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
        // txb_ISU_ENG_ABBRV.value = "";
        txa_NUSUAL_ISU_COND_CONTN.focus();
        return false;
    }
};

/**
     * @method
     * @name changeCfi
     * @description cfi 변경 설정 - 채권과 동일 .....
     * @returns {void}
     * @hidden N
     */
scwin.changeCfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    let cfi = "";
    cfi = "D";
    if (cmb_cb_p_group.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_group.getValue();
    if (cmb_cb_p_attr_1.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_1.getValue();
    if (cmb_cb_p_attr_2.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_2.getValue();
    if (cmb_cb_p_attr_3.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_3.getValue();
    if (cmb_cb_p_attr_4.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_4.getValue();
    txb_CFI_CD.setValue(cfi); // cfi 설정

};

/**
 * @method
 * @name setChange
 * @description 상세 조회시 CFI 상세 설정
 * @param {String} str_cfi str_cfi
 * @returns {void}
 * @hidden N
 */
scwin.setChange = function(str_cfi) {
    if (str_cfi === "") return;
    cmb_cb_p_group.setValue(str_cfi.substring(1, 2));
    cmb_cb_p_attr_1.setValue(str_cfi.substring(2, 3));
    cmb_cb_p_attr_2.setValue(str_cfi.substring(3, 4));
    cmb_cb_p_attr_3.setValue(str_cfi.substring(4, 5));
    cmb_cb_p_attr_4.setValue(str_cfi.substring(5, 6));
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);

    // PanelToGroupBox(panel_3);
    // PanelToGroupBox(panel_5);
    // PanelToGroupBox(panel_6);

    // cfi콤보셋팅
    ins_cfi_set(dts_cfi_group, "ULDINS16200.xml", SCREN_PROCS_TP_CD_01, "07", "D", "", "", "G");
    ins_combo_set(dts_CURR_TP_CD, "ULDINS16200.xml", SCREN_PROCS_TP_CD_01, "02475", "SEL"); // 02475 -통화구분 코드
    ins_combo_set(dts_DOM_FORN_ISU_TP_CD, "ULDINS16200.xml", SCREN_PROCS_TP_CD_01, "03407", "SEL"); // 03407 - 국내해외
    ins_combo_set(dts_BND_TP_CD, "ULDINS16200.xml", SCREN_PROCS_TP_CD_01, "01422", "SEL"); // 01422 - 채권종목의 유형을 나타냄
    ins_combo_set(dts_MUNIBND_TP_CD, "ULDINS16200.xml", SCREN_PROCS_TP_CD_01, "03076", "SEL"); // 03076 - 지방채구분코드
    ins_combo_set(dts_LIST_STAT_CD, "ULDINS16200.xml", SCREN_PROCS_TP_CD_01, "00714", "SEL"); // 00714 - D:상장폐지I:미발행N:비상장Y:상장Z:기타
    ins_combo_set(dts_BYINST_CREDIT_VALU_GRD, "ULDINS16200.xml", SCREN_PROCS_TP_CD_01, "03528", "CPBO"); // 03532 - 신용등급
    ins_combo_set(dts_STD_CD_APCT_TP_CD, "ULDINS16200.xml", SCREN_PROCS_TP_CD_01, "03527"); // 03527 - 신청자구분
    fn_CtrlBtn_temp("no_data");

    // hidden패널
    panel_12.hide();

    // 2016.09.20 표준코드 ID 생성으로 인한 필요없는 항목 삭제----------------------------------
    btn_clearPwd.hide();
    // 2016.09.20 표준코드 ID 생성으로 인한 필요없는 항목 삭제----------------------------------

    const arrObjectApct = [txb_APCT_NM, txb_APCT_FAX_NO, txb_APCT_TEL_NO, txb_APCT_INNR_NO];
    for (let i = 0; i < arrObjectApct.length; i++) {
        fn_apct_delchar(arrObjectApct[i]);
    }
    txb_pSTD_CD.focus();
};

/**
 * @method
 * @name btn_file_onclick
