/**
 * @method
 * @name dts_detail_OnLoadCompleted
 * @description dts_detail 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_detail_OnLoadCompleted = async function(rowcount) {
    if (rowcount > 0) {
        const CFI_CD = dts_detail.getCellData(dts_detail.getRowPosition(), "CFI_CD");
        const SIMSA_YN = dts_detail.getCellData(dts_detail.getRowPosition(), "SIMSA_YN");
        const LIST_STAT_CD = dts_detail.getCellData(dts_detail.getRowPosition(), "LIST_STAT_CD");
        // set_Change("ECVTCN") ;
        scwin.setChange(CFI_CD);
        fn_CtrlBtn_temp("update");
        // 전자단기사채일경우에만
        const STD_CD_APPL_ID = dts_detail.getCellData(dts_detail.getRowPosition(), "STD_CD_APPL_ID");
        let CP_BND_TP_CD = dts_detail.getCellData(dts_detail.getRowPosition(), "CP_BND_TP_CD");
        // alert(CP_BND_TP_CD);alert(dts_detail.NameValue(dts_detail.RowPosition,"EXP_PAY_AMT"));
        if (CP_BND_TP_CD === "BO") {
            await scwin.setBoView(SIMSA_YN, LIST_STAT_CD);
            panel_4.show("");
            scwin.CPBO = "전자단기사채";
            txb_gubun.setValue("" + scwin.CPBO);
        } else {
            panel_4.hide();
            scwin.CPBO = "CP";
            txb_gubun.setValue("" + scwin.CPBO);
        }
    } else {
        scwin.setChange("");
        fn_CtrlBtn_temp("no_data");
    }
};

