 * @name dts_detail_OnColumnChanged
 * @description detail On Column Changed 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_detail_OnColumnChanged = async function(row, colid) {
    if (colid === "ISU_DD") {
        let ISU_DD = edt_ISU_DD.getValue();
        const ISU_DD2 = dts_detail.getCellData(dts_detail.getRowPosition(), "ISU_DD2");
        if (ISU_DD === "") return;
        if (ISU_DD2 === "") return;
        ISU_DD = ISU_DD.substring(0, 6);
        const ISU_DD3 = ISU_DD2.substring(0, 6);
        if (ISU_DD === ISU_DD3) {

        } else {
            await $c.win.alert("발행년월은 변경이 안됩니다.");
            edt_ISU_DD.setValue(ISU_DD2);
            dts_detail.setCellData(dts_detail.getRowPosition(), "ISU_DD", ISU_DD2);
        }
    }
};

